"""Full fixed D CMVM, existing ISOURCE, RF60..95 and dead current-hg Ug.

Compiler is only required by --compile. Baked plans below execute under the
ordinary NumPy environment. A compact 16-byte control record per instruction
is fetched through the existing coefficient pool/CR256 response, so execution
does not assume a second instruction ROM or uncharged source-ROM replacement.
"""
from __future__ import annotations

from collections import Counter
from pathlib import Path
import json
import sys

import numpy as np

SCRATCH = tuple(range(60, 96))
LIMIT = 1 << 47


def _reference(kind, index, shift=0, negative=False):
    assert kind in (0, 1, 2) and 0 <= index < 256 and 0 <= shift < 48
    return [kind, index, shift, int(negative)]


def _reg(kind, index, hg):
    if kind == 0:
        assert index < 10
        return 30+index*3+hg
    if kind == 1:
        if index < len(SCRATCH):
            return SCRATCH[index]
        assert index < len(SCRATCH)+10
        return 30+(index-len(SCRATCH))*3+hg
    if kind == 2:
        assert index < 10
        return index*3+hg
    raise ValueError(kind)


def _compile_schedule(graph):
    """Fixed last_use_pressure; reclaim current-hg inputs at last use.

    Continue a failed physical allocation with virtual overflow slots only to
    report this same order's maximum requirement; such a plan cannot execute.
    """
    original = graph['nodes']
    nodes = []
    for n in original:
        if n['kind'] == 'input':
            nodes.append(dict(id=n['id'], kind='input', parents=[]))
        else:
            nodes.append(dict(id=n['id'], kind='addsub', parents=[
                (n['lhs'], n['lhs_shift'], False),
                (n['rhs'], n['rhs_shift'], n['subtract'])]))
    for out in graph['outputs']:
        nodes.append(dict(id=len(nodes), kind='accumulate', output_t=out['t'],
                          parents=[(out['node'], out['shift'], out['sign'] < 0)]))
    parent_ids = {n['id']: {r[0] for r in n['parents']} for n in nodes}
    use = Counter(p for n in nodes[10:] for p in parent_ids[n['id']])
    children = {n['id']: [] for n in nodes}
    for n in nodes[10:]:
        for p in parent_ids[n['id']]:
            children[p].append(n['id'])
    height = {}
    for n in reversed(nodes):
        height[n['id']] = 2+max((height[i] for i in children[n['id']]), default=0)
    refs = {i: (0, i) for i in range(10)}
    free = set(range(len(SCRATCH)))
    pending = set(range(10, len(nodes)))
    ready = {i: 0 for i in range(10)}
    rows, assignments = [], []
    slot = peak = 0
    peak_work = 10
    next_virtual = len(SCRATCH)+10
    first_overflow = None
    reclaimed_inputs = []
    while pending:
        eligible = [i for i in pending if all(p in ready and ready[p] <= slot for p in parent_ids[i])]
        if not eligible:
            rows.append(bytes(16))
            slot += 1
            continue
        def score(i):
            return (nodes[i]['kind'] == 'accumulate', sum(use[p] == 1 for p in parent_ids[i]), height[i], -i)
        i = max(eligible, key=score)
        n = nodes[i]
        operands = [_reference(*refs[p], shift, negative) for p, shift, negative in n['parents']]
        for p in parent_ids[i]:
            use[p] -= 1
            if use[p] == 0:
                typ, index = refs[p]
                free.add(index if typ == 1 else len(SCRATCH)+index)
                if typ == 0:
                    reclaimed_inputs.append(dict(input=p, slot=slot))
                del refs[p]
        if n['kind'] == 'accumulate':
            t = n['output_t']
            row = [2, t] + _reference(2, t) + operands[0]
        else:
            if not free:
                if first_overflow is None:
                    first_overflow = dict(node=i, slot=slot, completed_nodes=len(assignments))
                free.add(next_virtual)
                next_virtual += 1
            dst = min(free)
            free.remove(dst)
            refs[i] = (1, dst)
            row = [1, dst] + operands[0] + operands[1]
        row += [0]*(16-len(row))
        assert len(row) == 16
        rows.append(bytes(row))
        assignments.append(dict(node=i, slot=slot, kind=n['kind']))
        pending.remove(i)
        ready[i] = slot+2
        peak = max(peak, sum(r[0] == 1 for r in refs.values()))
        peak_work = max(peak_work, len(refs))
        slot += 1
    adapted = first_overflow is None
    return dict(adapted=adapted, reason=None if adapted else 'Fixed order exceeds 36 scratch plus dead current-hg Ug',
                control_hex=b''.join(rows).hex() if adapted else None, instructions=len(rows),
                arithmetic_addsub=sum(n['kind'] == 'addsub' for n in nodes),
                output_accumulate=sum(n['kind'] == 'accumulate' for n in nodes),
                scheduled_nops=len(rows)-len(assignments), scratch_capacity=len(SCRATCH),
                peak_live_scratch=peak, peak_live_work_vectors=peak_work,
                required_RF_for_this_order=50+peak_work,
                extra_vectors_for_this_order=next_virtual-(len(SCRATCH)+10),
                reclaimed_inputs=reclaimed_inputs, first_overflow=first_overflow,
                policy='fixed last_use_pressure with current-hg last-use reclamation and early output accumulation',
                graph_order_assignments=assignments)


def compile_plan(axis, D):
    """One full10x10 official da4ml0.6.0 wmc/auto call; no search sweep."""
    from importlib.metadata import version
    assert version('da4ml') == '0.6.0'
    root_open = Path(__file__).resolve().parent.parents[1]
    base = root_open.parent
    sys.path.insert(0, str(base/'algorithm/patch_probe/residual_consumer_probe/projection_chain/fast_temporal_recovery_lifting40'))
    import ordinary_source_cmvm as cmvm
    D = np.asarray(D, np.int64)
    assert D.shape == (10, 10)
    options = dict(method0='wmc', method1='auto', hard_dc=-1, decompose_dc=-2,
                   qintervals=[(float(cmvm.LOW), float(cmvm.HIGH), 1.)]*10,
                   adder_size=1, carry_size=1, search_all_decompose_dc=True)
    solved = cmvm.solve(np.ascontiguousarray(D.T, dtype=np.float32), **options)
    assert np.array_equal(solved.kernel, D.T)
    graph = cmvm.flatten(solved, D, -cmvm.LOW, np.array([cmvm.LOW]), np.array([cmvm.HIGH]))
    cmvm.precise_domain(graph)
    plan = _compile_schedule(graph)
    plan.update(name=axis+'_full_g_q8_D', axis=axis, D=D.tolist(), da4ml='0.6.0',
                method0='wmc', method1='auto', input_domain=[cmvm.LOW, cmvm.HIGH],
                constant_graph_no_RNE=True, entire_D_matrix=True,
                graph_arithmetic_nodes=sum(n['kind']=='addsub' for n in graph['nodes']),
                graph_outputs=len(graph['outputs']),
                graph=dict(nodes=[{k:n[k] for k in ('id','kind','source','lhs','rhs','lhs_shift','rhs_shift','subtract') if k in n}
                                  for n in graph['nodes']],
                           outputs=[{k:o[k] for k in ('t','node','shift','sign')} for o in graph['outputs']]),
                max_graph_node_signed_bits=max(n['signed_bits'] for n in graph['nodes']),
                max_operator_signed_bits=max(n.get('conservative_operator_bits', n['signed_bits']) for n in graph['nodes']))
    if plan['adapted']:
        plan['control_bytes'] = len(bytes.fromhex(plan['control_hex']))
        plan['padded_control_bytes'] = (plan['control_bytes']+31)//32*32
    return plan


def _compile_spilled_schedule(plan):
    """Same arithmetic order; deterministic farthest-next-use physical spills."""
    graph = plan['graph']
    nodes = []
    for n in graph['nodes']:
        nodes.append(dict(id=n['id'], kind=n['kind'], parents=[] if n['kind']=='input' else [
            (n['lhs'],n['lhs_shift'],False),(n['rhs'],n['rhs_shift'],n['subtract'])]))
    for out in graph['outputs']:
        nodes.append(dict(id=len(nodes), kind='accumulate', output_t=out['t'],
                          parents=[(out['node'],out['shift'],out['sign']<0)]))
    order = [a['node'] for a in plan['graph_order_assignments']]
    assert set(order) == set(range(10,len(nodes)))
    future = {n['id']:[] for n in nodes}
    for pos,i in enumerate(order):
        for p in {r[0] for r in nodes[i]['parents']}:
            future[p].append(pos)
    resident = {j:len(SCRATCH)+j for j in range(10)}
    free = set(range(len(SCRATCH)))
    backing, free_backing = {}, set()
    next_backing = stores = loads = 0
    rows = []

    def emit(fields):
        rows.append(bytes(fields+[0]*(16-len(fields))))

    def acquire(protected):
        nonlocal next_backing, stores
        if not free:
            victim = max((p for p in resident if p not in protected),
                         key=lambda p:(future[p][0] if future[p] else len(order), p))
            reg = resident.pop(victim)
            assert future[victim], 'dead values should already be freed'
            if victim not in backing:
                if free_backing:
                    slot = min(free_backing); free_backing.remove(slot)
                else:
                    slot = next_backing; next_backing += 1
                backing[victim] = slot
                emit([3,reg]+list((slot*48).to_bytes(4,'little')))
                stores += 1
            free.add(reg)
        reg = min(free); free.remove(reg)
        return reg

    for pos,i in enumerate(order):
        n = nodes[i]
        parents = {r[0] for r in n['parents']}
        for p in sorted(parents):
            if p not in resident:
                reg = acquire(parents)
                assert p in backing
                emit([4,reg]+list((backing[p]*48).to_bytes(4,'little')))
                resident[p] = reg
                loads += 1
        operands = [_reference(1,resident[p],s,neg) for p,s,neg in n['parents']]
        for p in parents:
            assert future[p].pop(0) == pos
            if not future[p]:
                free.add(resident.pop(p))
                if p in backing:
                    free_backing.add(backing.pop(p))
        if n['kind'] == 'accumulate':
            emit([2,n['output_t']]+_reference(2,n['output_t'])+operands[0])
        else:
            dst = acquire(parents)
            resident[i] = dst
            emit([1,dst]+operands[0]+operands[1])
    assert not backing and not resident
    result = dict(plan)
    result.update(adapted=True, reason=None, no_spill_adapted=False,
                  adaptation='same full graph and arithmetic order with paid signed48 SRAM spills',
                  control_hex=b''.join(rows).hex(), instructions=len(rows),
                  scheduled_nops=0, spill_stores_per_hg=stores, spill_loads_per_hg=loads,
                  spill_bytes=next_backing*48, physical_work_vectors=len(SCRATCH)+10,
                  spill_policy='fixed farthest-next-use, retain clean SRAM copies until last use',
                  control_bytes=len(rows)*16,padded_control_bytes=(len(rows)*16+31)//32*32)
    return result


def get_plan(axis, D):
    plan = COMPILED_PLANS[axis]
    assert np.array_equal(np.asarray(D, np.int64), np.asarray(plan['D'], np.int64)), 'CSE plan belongs to another deployed D'
    if not plan['adapted']:
        raise RuntimeError(plan['reason'])
    return plan


def control_image(plan):
    assert plan['adapted']
    blob = bytes.fromhex(plan['control_hex'])
    assert len(blob) == plan['instructions']*16
    return blob


def bind_control(m, plan, control_base, spill_base=None):
    """Call after root's actual DMA fill of control_image into coefficient pool."""
    blob = control_image(plan)
    assert control_base % 32 == 0 and 0 <= control_base <= len(m.coef)-len(blob)
    assert bytes(m.coef[control_base:control_base+len(blob)]) == blob
    if not hasattr(m, '_latent_cse_controls'):
        m._latent_cse_controls = {}
    if plan.get('spill_bytes',0):
        assert spill_base is not None, 'Caller must reserve and specify actual SRAM spill space'
        assert spill_base % 8 == 0 and 0 <= spill_base <= len(m.state)-plan['spill_bytes']
    m._latent_cse_controls[plan['name']] = (int(control_base),spill_base)


def _spill48(m, reg, address, store):
    """One existing64B staging allocation, actual SR64/SW64, no host spill dict."""
    assert address % 8 == 0 and len(m.common_staging)==64
    m.wait_reg(reg)
    if store:
        values = m.rf[reg].astype(np.int64)
        assert np.all(values>=-LIMIT) and np.all(values<LIMIT)
        m.advance(tag='latent_CSE_spill_RF_to_staging')
        m.common_staging[:48] = b''.join(int(v).to_bytes(6,'little',signed=True) for v in values)
        m.count['latent_CSE_spill_RF_vector_reads'] += 1
        for off in range(0,48,8):
            m.advance(write=(address+off,bytes(m.common_staging[off:off+8])),tag='latent_CSE_spill_SW64')
    else:
        for off in range(0,48,8):
            m.common_staging[off:off+8] = m.read_word(address+off)
        m.advance(tag='latent_CSE_reload_collector48')
        values = [int.from_bytes(m.common_staging[off:off+6],'little',signed=True) for off in range(0,48,6)]
        m.advance(op=('ILOAD',reg,values),tag='latent_CSE_reload_RF_load')
        m.wait_reg(reg)
    m.packed_coeff_valid = False


def execute_latent_cse(m, plan, hg):
    """Accumulate D*Ug into Uq, hg=0/1/2. All operands stay in actual RF.

    Inputs Ug[10,24] = RF30..59. Existing Uq[10,24] = RF0..29.
    This call overwrites RF60..95 and dead current-hg Ug inputs; any Uc
    cached there must be added before this call or explicitly reloaded later.
    Instruction fields are decoded from actual CR256 responses, not from
    host D values. Cold fill is caller-owned; each runtime CR fetch is paid.
    """
    assert plan['adapted'] and hg in (0, 1, 2)
    base, spill_base = m._latent_cse_controls[plan['name']]
    for j in range(10):
        r = 30+j*3+hg
        m.wait_reg(r)
        assert np.all(m.rf[r] >= -(1<<23)) and np.all(m.rf[r] < (1<<23))
    for pc in range(plan['instructions']):
        address = base+pc*16
        m.coefficient(address)
        assert m.caddr == address//32*32
        offset = address % 32
        fields = list(m.cword[offset:offset+16])
        assert len(fields) == 16
        kind, index = fields[:2]
        m.count['latent_CSE_control128_words'] += 1
        if kind in (3,4):
            assert not any(fields[6:]) and spill_base is not None
            offset = int.from_bytes(bytes(fields[2:6]),'little')
            assert offset % 48 == 0 and offset+48 <= plan['spill_bytes']
            _spill48(m,_reg(1,index,hg),spill_base+offset,store=kind==3)
            continue
        assert not any(fields[10:])
        if kind == 0:
            assert not any(fields)
            m.advance(tag='latent_CSE_scheduled_nop')
            continue
        assert kind in (1, 2)
        dst = _reg(1, index, hg) if kind == 1 else index*3+hg
        operands = []
        for start in (2, 6):
            typ, i, shift, neg = fields[start:start+4]
            assert shift < 48 and neg in (0, 1)
            r = _reg(typ, i, hg)
            m.wait_reg(r)
            actual = m.rf[r].astype(np.int64)
            # Python integer extrema check occurs before NumPy shift to avoid
            # an overflowed int64 hiding a signed48 operand violation.
            lo, hi = int(actual.min())*(1<<shift), int(actual.max())*(1<<shift)
            if neg:
                lo, hi = -hi, -lo
            assert -LIMIT <= lo and hi < LIMIT
            operands.append(dict(reg=r, shift=shift, sign=-1 if neg else 1))
        m.wait_reg(dst)
        m.advance(op=('ISOURCE', dst, dict(kind='addsub', operands=operands)),
                  tag='latent_CSE_addsub' if kind == 1 else 'latent_CSE_accumulate_Uq')
        m.count['latent_CSE_operand_RF_vector_reads'] += 2
    for t in range(10):
        m.wait_reg(t*3+hg)
    m.count['latent_CSE_H8_calls'] += 1


def smoke_plan(plan, stress=False):
    """Real RF loaded through ILOAD; directed signed24 inputs, all three hg."""
    root_open = Path(__file__).resolve().parent.parents[1]
    sys.path.insert(0, str(root_open/'breadth_20260912/hardware'))
    import packed_weights as shared
    D = np.asarray(plan['D'], np.int64)
    # Includes negative inputs and broad signed24 extrema. Ug produced by the
    # deployed U is much narrower; the CSE graph is deliberately checked over
    # the same signed24 input box used by the ordinary compiler.
    x = np.arange(240, dtype=np.int64).reshape(10, 24)*719-85813
    x[:, :8] = np.array([-(1<<23), (1<<23)-1, -1, 0, 1, -2048, 2048, 999])[None, :]
    initial = np.arange(240, dtype=np.int64).reshape(10, 24)-119
    m = shared.PackedMachine(stress)
    m.phase = 'CSE_smoke_control_fill_and_RF_input'
    m.dma_input(control_image(plan), 73728, True)
    bind_control(m, plan, 73728, spill_base=98304)
    for t in range(10):
        for hg in range(3):
            m.advance(op=('ILOAD', t*3+hg, initial[t, hg*8:hg*8+8]), tag='directed_Uq_load')
            m.advance(op=('ILOAD', 30+t*3+hg, x[t, hg*8:hg*8+8]), tag='directed_Ug_load')
    m.drain()
    m.common_staging[48:64] = bytes(range(16))
    before, start = Counter(m.count), m.time
    m.phase = 'latent_CSE_smoke'
    for hg in range(3):
        execute_latent_cse(m, plan, hg)
        for other_hg in range(hg+1, 3):
            other_regs = [30+t*3+other_hg for t in range(10)]
            assert np.array_equal(m.rf[other_regs].astype(np.int64), x[:, other_hg*8:other_hg*8+8])
    actual = m.rf[:30].astype(np.int64).reshape(10, 24)
    expected = initial+D@x
    assert np.array_equal(actual, expected)
    assert m.common_staging[48:64] == bytes(range(16))
    assert sum(m.stages.values()) == m.time
    return dict(checked_values=240, differences=0, future_hg_Ug_preserved=True, stress=stress,
                post_fill_slots=m.time-start, counts=dict(Counter(m.count)-before))


