# END_BAKED_PLANS


def main():
    import argparse
    sys.dont_write_bytecode = True
    parser = argparse.ArgumentParser()
    parser.add_argument('--compile', action='store_true')
    parser.add_argument('--reallocate', action='store_true', help='Reallocate the already baked graph; do not call da4ml')
    parser.add_argument('--spill', action='store_true', help='Apply fixed paid spills to the baked full arithmetic order')
    args = parser.parse_args()
    assert sum((args.compile,args.reallocate,args.spill)) <= 1
    if args.compile or args.reallocate or args.spill:
        root_open = Path(__file__).resolve().parent.parents[1]
        compiled = {}
        for axis in ('ordinary', 'lifting_raw'):
            if args.compile:
                params = dict(np.load(root_open/'breadth_20260912/representation/parameters'/f'{axis}.npz'))
                print('COMPILING_FULL_D', axis, flush=True)
                plan = compile_plan(axis, params['full_g_q8_D'])
            elif args.reallocate:
                old = COMPILED_PLANS[axis]
                plan = _compile_schedule(old['graph'])
                for k in ('name','axis','D','da4ml','method0','method1','input_domain',
                          'constant_graph_no_RNE','entire_D_matrix','graph_arithmetic_nodes',
                          'graph_outputs','graph','max_graph_node_signed_bits','max_operator_signed_bits'):
                    plan[k] = old[k]
                if plan['adapted']:
                    plan['control_bytes'] = len(bytes.fromhex(plan['control_hex']))
                    plan['padded_control_bytes'] = (plan['control_bytes']+31)//32*32
            else:
                plan = _compile_spilled_schedule(COMPILED_PLANS[axis])
            if plan['adapted']:
                plan['directed_smoke'] = smoke_plan(plan)
            compiled[axis] = plan
            print(json.dumps({k:v for k,v in plan.items() if k not in ('control_hex','D','graph_order_assignments','graph','live_scratch_at_failure')}), flush=True)
        path = Path(__file__)
        source = path.read_text()
        left = source.index('# BEGIN_BAKED_PLANS')+len('# BEGIN_BAKED_PLANS')
        right = source.index('# END_BAKED_PLANS')
        body = '\nCOMPILED_PLANS = json.loads('+repr(json.dumps(compiled, separators=(',', ':')))+')\n'
        path.write_text(source[:left]+body+source[right:])
    else:
        assert COMPILED_PLANS, 'compile once under the existing da4ml0.6 environment'
        for axis, plan in COMPILED_PLANS.items():
            print(axis, json.dumps(smoke_plan(plan) if plan['adapted'] else plan))


if __name__ == '__main__':
    main()
